      match goal with X : wmono _ _ m1 |- _ => rename X into WMl end;
      match goal with X : mem_inv _ m1 |- _ => rename X into MIl end;
      try match goal with X : stk _ m1 _ _ |- _ => rename X into STl end.
    Ltac breg1 := first [ eassumption | reflexivity
